import{_ as t,o as a,c as d,a4 as r}from"./chunks/framework.B6zrJok8.js";const u=JSON.parse('{"title":"CLI Reference","description":"","frontmatter":{},"headers":[],"relativePath":"cli/index.md","filePath":"cli/index.md","lastUpdated":null}'),o={name:"cli/index.md"};function i(c,e,l,s,n,h){return a(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="cli-reference" tabindex="-1">CLI Reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI Reference&quot;">​</a></h1><p>The SFCC Campaign Automation CLI is split into two command sets:</p><ul><li><strong>Producer Commands</strong> — the daily workflow for web producers</li><li><strong>Dev Commands</strong> — power tools for the web developer</li></ul><h2 id="producer-commands" tabindex="-1">Producer Commands <a class="header-anchor" href="#producer-commands" aria-label="Permalink to &quot;Producer Commands&quot;">​</a></h2><p>These commands handle the entire daily flow. Most use the <a href="/cli/select.html">sticky date</a> automatically.</p><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><a href="/cli/pull.html"><code>pull</code></a></td><td>Git sync + fetch data + status dashboard + date prompt</td></tr><tr><td><a href="/cli/select.html"><code>select</code></a></td><td>Set or switch the working date (sticky)</td></tr><tr><td><a href="/cli/build.html"><code>build</code></a></td><td>Generate HTML + OCAPI payload (guarded)</td></tr><tr><td><a href="/cli/refresh.html"><code>edit</code></a></td><td>Force-rebuild after template edits</td></tr><tr><td><a href="/cli/preview.html"><code>preview</code></a></td><td>Compose multi-zone preview + show links</td></tr><tr><td><a href="/cli/push.html"><code>push</code></a></td><td>Validate data quality + sync to SFCC staging</td></tr><tr><td><a href="/cli/replicate.html"><code>replicate</code></a></td><td>Manual STG → POD replication checklist</td></tr><tr><td><a href="/cli/done.html"><code>done</code></a></td><td>Verify sync + generate changeout email</td></tr><tr><td><a href="/cli/status.html"><code>status</code></a></td><td>Unified dashboard (live, ready, build, new)</td></tr></tbody></table><h2 id="dev-commands" tabindex="-1">Dev Commands <a class="header-anchor" href="#dev-commands" aria-label="Permalink to &quot;Dev Commands&quot;">​</a></h2><p>Configuration, testing, registry management, and advanced operations.</p><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><a href="/cli/setup.html"><code>setup</code></a></td><td>Interactive configuration wizard</td></tr><tr><td><a href="/cli/upload.html"><code>upload</code></a></td><td>Partial sync — push only HTML changes (hotfix)</td></tr><tr><td><a href="/cli/delete.html"><code>delete</code></a></td><td>Remove a refresh from SFCC and local files</td></tr><tr><td><a href="/cli/registry.html"><code>registry</code></a></td><td>Manage the asset registry</td></tr><tr><td><a href="/cli/reports.html"><code>reports</code></a></td><td>Statistics, coverage, and date reports</td></tr><tr><td><a href="/cli/email.html"><code>email</code></a></td><td>Generate changeout email (standalone)</td></tr><tr><td><a href="/cli/health.html"><code>health</code></a></td><td>Check SFCC OCAPI connection</td></tr></tbody></table><h2 id="how-commands-route" tabindex="-1">How Commands Route <a class="header-anchor" href="#how-commands-route" aria-label="Permalink to &quot;How Commands Route&quot;">​</a></h2><p>All make commands call the unified CLI router at <code>src/cli/index.js</code>, which:</p><ol><li>Resolves the brand from config or <code>BRAND=</code> argument</li><li>Parses flags into an options object</li><li>Initializes a <code>BrandContext</code> (composition root)</li><li>Dispatches to the appropriate handler in <code>src/cli/commands/</code></li></ol><h2 id="daily-use-web-producers" tabindex="-1">Daily use (web producers) <a class="header-anchor" href="#daily-use-web-producers" aria-label="Permalink to &quot;Daily use (web producers)&quot;">​</a></h2><p><strong>You don’t need any flags for the normal workflow.</strong> Run:</p><ul><li><code>make pull</code> → pick your working date (sticky)</li><li><code>make build</code> → uses sticky date</li><li><code>make preview</code> → uses sticky date</li><li><code>make push</code> → uses sticky date; confirm if there are warnings</li><li><code>make done</code> → uses sticky date</li><li><code>make commit</code> → uses sticky date</li></ul><p>The app remembers your <strong>current refresh</strong> (date + r#) and shows “Current refresh: …” when it uses it. If a date has multiple refreshes, you’ll get a picker. No need to remember <code>DATE=</code> or <code>REFRESH=</code> for daily use.</p><h2 id="options-testing-and-automation" tabindex="-1">Options (testing and automation) <a class="header-anchor" href="#options-testing-and-automation" aria-label="Permalink to &quot;Options (testing and automation)&quot;">​</a></h2><p>Flags and Make variables are for <strong>scripts, CI, and power users</strong> when you need a specific date/refresh or non-interactive runs:</p><table tabindex="0"><thead><tr><th>Flag / Make var</th><th>Description</th></tr></thead><tbody><tr><td><code>--date=YYYY-MM-DD</code> / <code>DATE=</code></td><td>Override sticky date</td></tr><tr><td><code>--refresh=r1</code> / <code>REFRESH=</code></td><td>Override refresh (e.g. multi-refresh dates)</td></tr><tr><td><code>--yes</code> / <code>-y</code> / <code>YES=1</code></td><td>Skip confirmation prompts (e.g. push with warnings)</td></tr><tr><td><code>--force</code> / <code>FORCE=1</code></td><td>Bypass guards (re-push, force rebuild)</td></tr><tr><td><code>--dry-run</code></td><td>Show what would change without making changes</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/guides/producer-workflow.html">Producer Guide</a> — Daily guide</li><li><a href="/reference/commands.html">Commands Reference</a> — Full make command list (flags, daily use vs automation)</li><li><a href="/reference/architecture.html">Architecture</a> — System design</li></ul>',21)])])}const p=t(o,[["render",i]]);export{u as __pageData,p as default};
